$ErrorActionPreference = 'Stop'
$PSNativeCommandUseErrorActionPreference = $true
$env:TEMP = Join-Path $PSScriptRoot '.'
$env:TMP = $env:TEMP
$env:TMPDIR = $env:TEMP
$repository = 'lcv-leo/lcv-leo'
$publication = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'publication.json') -Raw | ConvertFrom-Json
$number = $publication.number
$expectedHead = $publication.head
$directory = Join-Path $PSScriptRoot 'initial-state'
New-Item -ItemType Directory -Path $directory -Force | Out-Null

function Save-GitHubRead {
    param([string]$Endpoint, [string]$Name, [switch]$Paginate)
    $arguments = @('api', $Endpoint, '-H', 'X-GitHub-Api-Version: 2026-03-10')
    if ($Paginate) { $arguments += @('--paginate', '--slurp') }
    $PSNativeCommandUseErrorActionPreference = $false
    $raw = & gh @arguments 2> (Join-Path $directory "$Name.stderr.txt")
    $exitCode = $LASTEXITCODE
    $raw | Set-Content -LiteralPath (Join-Path $directory "$Name.json") -Encoding utf8NoBOM
    if ($exitCode -ne 0) {
        return [pscustomobject]@{ observationError = $true; exitCode = $exitCode; evidence = "$Name.stderr.txt" }
    }
    return (($raw -join "`n") | ConvertFrom-Json)
}

$before = Save-GitHubRead "repos/$repository/pulls/$number" 'pull-before'
if ($before.head.sha -ne $expectedHead) { throw 'Remote head changed before collection; preserved pull-before evidence.' }
$reviews = Save-GitHubRead "repos/$repository/pulls/$number/reviews?per_page=100" 'reviews' -Paginate
$comments = Save-GitHubRead "repos/$repository/issues/$number/comments?per_page=100" 'conversation-comments' -Paginate
$inline = Save-GitHubRead "repos/$repository/pulls/$number/comments?per_page=100" 'review-comments' -Paginate
$checks = Save-GitHubRead "repos/$repository/commits/$expectedHead/check-runs?per_page=100&filter=all" 'check-runs' -Paginate
$statuses = Save-GitHubRead "repos/$repository/commits/$expectedHead/status?per_page=100" 'commit-status' -Paginate
$runs = Save-GitHubRead "repos/$repository/actions/runs?head_sha=$expectedHead&per_page=100" 'workflow-runs' -Paginate
$alerts = Save-GitHubRead "repos/$repository/code-scanning/alerts?state=open&ref=refs/pull/$number/head&per_page=100" 'code-scanning-alerts' -Paginate
$analyses = Save-GitHubRead "repos/$repository/code-scanning/analyses?ref=refs/pull/$number/head&per_page=100" 'code-scanning-analyses' -Paginate

$query = @'
query($number:Int!,$cursor:String) {
  repository(owner:"lcv-leo", name:"lcv-leo") {
    pullRequest(number:$number) {
      headRefOid baseRefOid state isDraft mergeStateStatus autoMergeRequest { enabledAt }
      reviewThreads(first:100,after:$cursor) {
        pageInfo { hasNextPage endCursor }
        nodes { id isResolved isOutdated path line startLine originalLine
          comments(first:100) { pageInfo { hasNextPage endCursor }
            nodes { id databaseId body createdAt url author { login } }
          }
        }
      }
    }
  }
}
'@
$cursor = $null
$threads = [Collections.Generic.List[object]]::new()
$pageNumber = 0
do {
    $arguments = @('api','graphql','-f',"query=$query",'-F',"number=$number")
    if ($null -ne $cursor) { $arguments += @('-f',"cursor=$cursor") }
    $raw = & gh @arguments
    $raw | Set-Content -LiteralPath (Join-Path $directory "review-threads-$pageNumber.json") -Encoding utf8NoBOM
    $page = ($raw -join "`n") | ConvertFrom-Json
    if ($page.errors) { throw 'GraphQL thread collection failed; see preserved response.' }
    $pull = $page.data.repository.pullRequest
    foreach ($thread in $pull.reviewThreads.nodes) {
        $threads.Add($thread)
        if ($thread.comments.pageInfo.hasNextPage) {
            throw 'Thread comments exceed the initial page; continue nested pagination before handoff.'
        }
    }
    $cursor = $pull.reviewThreads.pageInfo.endCursor
    $pageNumber++
} while ($pull.reviewThreads.pageInfo.hasNextPage)

$after = Save-GitHubRead "repos/$repository/pulls/$number" 'pull-after'
if ($after.head.sha -ne $expectedHead) { throw 'Remote head changed during collection; inventory is stale.' }
$reviewItems = @($reviews | ForEach-Object { $_ })
$summary = [ordered]@{
    capturedAtUtc = [DateTime]::UtcNow.ToString('o')
    url = $after.html_url
    number = $number
    head = $expectedHead
    base = $after.base.sha
    state = $after.state
    merged = $after.merged
    draft = $after.draft
    autoMerge = $after.auto_merge
    reviewCount = $reviewItems.Count
    reviews = @($reviewItems | Select-Object id,state,commit_id,submitted_at,@{n='author';e={$_.user.login}})
    unresolvedThreads = @($threads | Where-Object { -not $_.isResolved }).Count
    threadCount = $threads.Count
    conversationCommentCount = @($comments | ForEach-Object { $_ }).Count
    reviewCommentCount = @($inline | ForEach-Object { $_ }).Count
    checkRuns = @($checks.check_runs | ForEach-Object { $_ } | Select-Object id,name,status,conclusion,head_sha,details_url)
    workflows = @($runs.workflow_runs | ForEach-Object { $_ } | Select-Object id,name,event,status,conclusion,head_sha,html_url)
    codeScanningAlerts = @($alerts | ForEach-Object { $_ })
    codeScanningAnalyses = @($analyses | ForEach-Object { $_ } | Select-Object id,commit_sha,ref,error,warning)
}
$summary | ConvertTo-Json -Depth 15 | Set-Content -LiteralPath (Join-Path $directory 'summary.json') -Encoding utf8NoBOM
$summary | ConvertTo-Json -Depth 15

